package com.bank.onboarding;

import java.util.*;
import java.util.logging.*;

public class OnboardingDemo {
    private static final Logger log = Logger.getLogger("Onboarding");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = new ArrayList<>(List.of(
            new Employee(1L, "Rajesh", 2015),
            new Employee(2L, "Priya", 2022),
            new Employee(3L, "Amit", 2022),
            new Employee(4L, "Sneha", 2019),
            new Employee(5L, "Vikram", 2010)
        ));
        OnboardingService service = new OnboardingService();
        List<Employee> sorted = service.sortByJoiningDesc(staff);
        log.info("Onboarding review (newest joiners first):");
        sorted.forEach(e -> log.info(() ->
            String.format("  joined %d | %s", e.getYearOfJoining(), e.getName())));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final Long id;
    private final String name;
    private final int yearOfJoining;
    Employee(Long id, String name, int yearOfJoining) {
        this.id = id; this.name = name; this.yearOfJoining = yearOfJoining;
    }
    String getName() { return name; }
    int getYearOfJoining() { return yearOfJoining; }
}

// ─── Would be in service/OnboardingService.java ───
class OnboardingService {
    // Most recent first: reverse the ascending year order, then break ties by name.
    List<Employee> sortByJoiningDesc(List<Employee> employees) {
        return employees.stream()
            .sorted(Comparator.comparingInt(Employee::getYearOfJoining).reversed()
                .thenComparing(Employee::getName))
            .toList();
    }
}
